<?php require_once __DIR__.'/../../config/app.php'; if($_SERVER['REQUEST_METHOD']!=='POST') redirect('/pages/auth/login.php'); $email=trim($_POST['email']??'');$password=$_POST['password']??'';$err=[];if(!filter_var($email,FILTER_VALIDATE_EMAIL))$err['email']='Format email tidak valid.';if($password==='')$err['password']='Kata sandi wajib diisi.';if($err)failForm($err,['email'=>$email],'/pages/auth/login.php');$s=$pdo->prepare('SELECT id,name,email,password,role FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($password,$u['password']))failForm(['login'=>'Email atau kata sandi salah.'],['email'=>$email],'/pages/auth/login.php');session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];unset($_SESSION['old']);redirect('/index.php');